  await evaluate('void eval('+JSON.stringify(fs.readFileSync(path.join(__dirname,'../app/src/ui/moonlight-ui.js'),'utf8'))+');true');
  assert.match(await evaluate('document.getElementById("moonlight-hosts-status").textContent'),/Unreadable pairing data/);
  await evaluate('window.__moonlightSimpleUI.close();window.__failHostsLoad=false;true');
